<?php require_once '../config/auth.php';require_once '../config/database.php';require_once '../config/layout.php';require_role('hr');$id=(int)($_GET['id']??$_POST['id']??0);$s=$pdo->prepare('SELECT * FROM lowongan WHERE id_lowongan=? AND status="Disetujui"');$s->execute([$id]);$l=$s->fetch();if(!$l)die('Lowongan tidak ditemukan atau belum disetujui.');if($_SERVER['REQUEST_METHOD']==='POST'){$deadline=$_POST['deadline']?:null;$u=$pdo->prepare('UPDATE lowongan SET judul_lowongan=?,job_description=?,job_specification=?,jumlah_kebutuhan=?,deadline=?,status="Dipublikasikan",tanggal_publish=NOW() WHERE id_lowongan=?');$u->execute([trim($_POST['judul']),trim($_POST['desc']),trim($_POST['spec']),max(1,(int)$_POST['jumlah']),$deadline,$id]);$pdo->prepare('DELETE FROM tahapan_seleksi WHERE id_lowongan=?')->execute([$id]);$names=$_POST['tahap_nama']??[];$descs=$_POST['tahap_desc']??[];foreach($names as $i=>$name){$name=trim($name);if($name==='')continue;$q=$pdo->prepare('INSERT INTO tahapan_seleksi(id_lowongan,nama_tahapan,urutan,deskripsi) VALUES(?,?,?,?)');$q->execute([$id,$name,$i+1,trim($descs[$i]??'')]);}flash('Lowongan berhasil dipublikasikan.');header('Location: pengajuan.php');exit;}page_header('Lengkapi & Publish Lowongan');?><div class="card"><form method="post"><input type="hidden" name="id" value="<?=$id?>"><label>Job Title<input name="judul" value="<?=e($l['judul_lowongan'])?>" required></label><label>Jumlah Kebutuhan<input type="number" name="jumlah" min="1" value="<?=e($l['jumlah_kebutuhan'])?>" required></label><label>Job Description<textarea name="desc" required><?=e($l['job_description'])?></textarea></label><label>Job Specification<textarea name="spec" required><?=e($l['job_specification'])?></textarea></label><label>Deadline<input type="date" name="deadline" value="<?=e($l['deadline'])?>"></label><h3>Tahapan Seleksi</h3><div id="steps"><div class="card"><input name="tahap_nama[]" placeholder="Nama tahap, contoh: Seleksi Administrasi" required><textarea name="tahap_desc[]" placeholder="Deskripsi tahap"></textarea></div></div><button type="button" class="btn secondary" onclick="addStep()">+ Tambah Tahap</button><button class="btn success">Publish</button></form></div><script>function addStep(){const d=document.createElement('div');d.className='card';d.innerHTML='<input name="tahap_nama[]" placeholder="Nama tahap" required><textarea name="tahap_desc[]" placeholder="Deskripsi tahap"></textarea>';document.getElementById('steps').appendChild(d)}</script><?php page_footer();
